import{_ as a,a as o}from"./chunks/image66.La5G7dGo.js";import{_ as n}from"./chunks/image57.pPHO-JgT.js";import{_ as i}from"./chunks/2.BRgDBKom.js";import{_ as r,o as s,c as l,am as c}from"./chunks/framework.CenUaW7a.js";const d="/projects/AiMechaM1/en/advanced-kit/assets/10.1.Cme-8J7i.webp",t="/projects/AiMechaM1/en/advanced-kit/assets/10.2.GjQ8eHQF.webp",h="/projects/AiMechaM1/en/advanced-kit/assets/image72.C4B687z7.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image73.B4opqPVd.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image74.CXzqXwWw.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image77.BO9SQ6Fg.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image76.BR1Oz0Wo.png",j=JSON.parse('{"title":"3.10 Lesson 10: Dynamic Obstacle Avoidance Practice","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.10 Lesson 10 Dynamic Obstacle Avoidance Practice.md","filePath":"docs/3. Course materials/3.10 Lesson 10 Dynamic Obstacle Avoidance Practice.md"}'),f={name:"docs/3. Course materials/3.10 Lesson 10 Dynamic Obstacle Avoidance Practice.md"};function b(w,e,y,v,_,k){return s(),l("div",null,[...e[0]||(e[0]=[c('<h1 id="_3-10-lesson-10-dynamic-obstacle-avoidance-practice" tabindex="-1">3.10 Lesson 10: Dynamic Obstacle Avoidance Practice <a class="header-anchor" href="#_3-10-lesson-10-dynamic-obstacle-avoidance-practice" aria-label="Permalink to &quot;3.10 Lesson 10: Dynamic Obstacle Avoidance Practice&quot;">​</a></h1><h2 id="_3-10-1-lesson-introduction" tabindex="-1">3.10.1 Lesson Introduction <a class="header-anchor" href="#_3-10-1-lesson-introduction" aria-label="Permalink to &quot;3.10.1 Lesson Introduction&quot;">​</a></h2><p>As part of the embodied AI large model curriculum series, this lesson builds upon the distance-based sound and light alarm to advance from &quot;stopping at obstacles&quot; to &quot;steering around obstacles&quot; while introducing intelligent object following. Taking inspiration from autonomous driving obstacle avoidance and adaptive cruise control, ultrasonic ranging is combined with differential steering to illustrate active obstacle avoidance and dynamic following. Following the path of &quot;obstacle avoidance principles → variable introduction → avoidance implementation → following implementation → dual-mode integration&quot;, variable programming is introduced to transform obstacle stopping into left-turn avoidance and achieve three-speed object following. Integrating A for obstacle avoidance and B for object following establishes a dual-mode system that lays the foundation for intelligent navigation.</p><h2 id="_3-10-2-learning-objectives" tabindex="-1">3.10.2 Learning Objectives <a class="header-anchor" href="#_3-10-2-learning-objectives" aria-label="Permalink to &quot;3.10.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the working principle of ultrasonic dynamic obstacle avoidance. Master the closed-loop distance control logic for object following. Gain a thorough understanding of variable definition, assignment, and invocation, and learn the roles of target values and error margins in control systems.</p><p><strong>2.</strong> Create and use variables to store parameter values. Master independent rotational speed control commands for the left and right wheel groups to achieve differential steering. Proficiently apply multi-layer conditional judgments to implement three-speed following control.</p><p><strong>3.</strong> Establish a motion control mindset for differential steering. Cultivate a parameterized programming approach using variables. Strengthen logical thinking in closed-loop feedback control, and form an initial system design capability for integrating multi-mode programs.</p><p><strong>4.</strong> Connect obstacle avoidance and object following technologies to real-world application scenarios such as autonomous vehicles, factory AGV transport robots, following service robots, and tracking drones.</p><h2 id="_3-10-3-preparation" tabindex="-1">3.10.3 Preparation <a class="header-anchor" href="#_3-10-3-preparation" aria-label="Permalink to &quot;3.10.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-wheel robot base × 1</p></li><li><p>Type-C USB data cable × 1</p></li><li><p>Computer running Windows or macOS × 1</p></li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>Core Concept Description</strong>:</p><p><strong>Variable</strong>: A variable acts like a reusable label attached to data, serving as a data container that can be stored, modified, and called at any time. Once created, a variable can be assigned new values or read whenever needed, eliminating the need to repeatedly enter the same numerical value.</p><p><strong>Obstacle Avoidance Principle:</strong> This process mirrors how a pedestrian navigates around an obstacle. First, the ultrasonic sensor acts as the eyes to measure distance ahead. Next, the program acts as the brain, detecting the obstacle and deciding to take a detour. Finally, differential motor control acts as the feet, steering the car to the left by creating a speed difference between the left and right wheels.</p><p><strong>Object Following Principle</strong>: Similar to walking behind a person, the ultrasonic sensor continuously measures distance like eyes locked onto a target. → The program evaluates distance intervals to speed up when too far or slow down when too close. → Three-stage motor speed regulation drives the car forward or backward accordingly.</p><p><strong>Hardware Port</strong>: Connect the ultrasonic sensor to port K.</p><h2 id="_3-10-4-hands-on-project" tabindex="-1">3.10.4 Hands-On Project <a class="header-anchor" href="#_3-10-4-hands-on-project" aria-label="Permalink to &quot;3.10.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project features two core functions, obstacle avoidance and object following, operating as two independent key-triggered modes. The obstacle avoidance mode relies on the ultrasonic sensor to measure distance. When the distance is less than 10 cm, left-right wheel speed differentials steer the car to the left to bypass the obstacle while activating a sound and light alarm, whereas normal distances keep the car driving straight. The object following mode sets a 40 cm target following distance with a 10 cm safety margin, dividing the range into three distance intervals to maintain a stable following distance via closed-loop control of moving forward, stopping, and moving backward. Triggered separately by the A Key and the B key, the two modes run independently without interfering with each other.</p><img loading="lazy" height="540" width="960" src="'+d+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><img loading="lazy" height="540" width="960" src="'+t+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="758" width="1209" src="'+h+'" class="common_img" style="width:700px;aspect-ratio:1209 / 758;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Variable operation</td><td style="text-align:center;"><img loading="lazy" height="81" width="211" src="'+p+'" class="common_img" style="width:190px;aspect-ratio:211 / 81;"></td><td style="text-align:left;">Creates a new variable container to store data.</td></tr><tr><td style="text-align:center;">Variable operation</td><td style="text-align:center;"><img loading="lazy" height="102" width="464" src="'+g+'" class="common_img" style="width:200px;aspect-ratio:464 / 102;"></td><td style="text-align:left;">Assigns a specified numerical value to a variable.</td></tr><tr><td style="text-align:center;">Sensor reading</td><td style="text-align:center;"><img loading="lazy" height="76" width="414" src="'+a+'" class="common_img" style="width:200px;aspect-ratio:414 / 76;"></td><td style="text-align:left;">Reads the real-time distance value.</td></tr><tr><td style="text-align:center;">Differential control</td><td style="text-align:center;"><img loading="lazy" height="145" width="688" src="'+n+'" class="common_img" style="width:400px;aspect-ratio:688 / 145;"></td><td style="text-align:left;">Independently controls the rotational speeds of the left and right wheel groups.</td></tr><tr><td style="text-align:center;">Buzzer control</td><td style="text-align:center;"><img loading="lazy" height="66" width="594" src="'+o+'" class="common_img" style="width:300px;aspect-ratio:594 / 66;"></td><td style="text-align:left;">Triggers an alarm tone during obstacle avoidance.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Obstacle Avoidance Implementation</strong></p><ul><li><p>Trigger condition: Start the program when the A key is short-pressed, with an outer repeat forever loop.</p></li><li><p>Conditional judgment: Check whether the ultrasonic distance is less than or equal to 10 cm.</p></li><li><p>Obstacle encountered branch: Play note D3 for a 1/2 beat in the background. + Set the ultrasonic RGB lights to red, set the left wheels to 10 rpm. + Set the right wheels to 60 rpm, and wait 0.5 s.</p></li><li><p>Normal branch: Move the car straight ahead at 10 rpm. + Set the ultrasonic RGB lights to blue. + Wait 0.5 s.</p></li><li><p>Differential principle: Driving the right wheels faster than the left wheels steers the car to the left, resuming straight driving once the obstacle is bypassed.</p></li></ul><img loading="lazy" height="693" width="729" src="'+m+'" class="common_img" style="width:600px;aspect-ratio:729 / 693;"><p><strong>Task 2: Object Following Program</strong></p><ul><li><p>Initialization: Create a <code>target following distance</code> variable set to 40, and create a <code>safety margin</code> variable set to 10.</p></li><li><p>Trigger condition: Start the program when the B key is short-pressed, running inside a repeat forever loop.</p></li><li><p>Stage 1: When the distance is greater than the target plus the margin, meaning greater than 50 cm. → Drive forward at 20% power.</p></li><li><p>Stage 2: When the distance is between the target minus the margin and the target plus the margin, meaning between 30 cm and 50 cm. → Stop the car.</p></li><li><p>Stage 3: When the distance is less than the target minus the margin, meaning less than 30 cm. → Drive backward at 20% power.</p></li></ul><img loading="lazy" height="556" width="1240" src="'+u+'" class="common_img" style="width:700px;aspect-ratio:1240 / 556;"><img loading="lazy" height="540" width="960" src="'+t+'" class="common_img" style="width:700px;aspect-ratio:960 / 540;"><p><strong>Task 3: Dual-Mode Integrated Program</strong></p><ul><li><p>Initialize two variables at startup: Set target following distance to 40 cm and safety margin to 10 cm.</p></li><li><p>When the A key is short-pressed: Start the obstacle avoidance mode to steer left around obstacles.</p></li><li><p>When the B key is short-pressed: Start the object-following mode for three-speed dynamic following.</p></li><li><p>The two modes operate independently and switch functions via key presses.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Dynamic Obstacle Avoidance Practice</a>.</strong></p></div></li></ul><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+i+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-10-5-expansion-and-advancement" tabindex="-1">3.10.5 Expansion and Advancement <a class="header-anchor" href="#_3-10-5-expansion-and-advancement" aria-label="Permalink to &quot;3.10.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Intelligent Obstacle Avoidance Path Optimization</strong></p><p>Upgrade the obstacle avoidance logic by adding turning duration control so that the car resumes straight driving after turning a specific angle, completing a full detour trajectory. Implement an S-shaped avoidance path by turning left, driving forward, and then turning right to make the avoidance maneuver smoother rather than spinning continuously in place.</p><p><strong>Project 2: Intelligent Following with Speed Gradients</strong></p><p>Upgrade the three-stage following system to multi-stage gradient following, driving faster at greater distances and slower at closer distances for smooth acceleration and deceleration. To clearly indicate the device&#39;s state, incorporate RGB status lights that glow green when moving forward, yellow when stopped, and red when moving backward.</p><h2 id="_3-10-6-q-a" tabindex="-1">3.10.6 Q&amp;A <a class="header-anchor" href="#_3-10-6-q-a" aria-label="Permalink to &quot;3.10.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is the primary purpose of setting a 10 cm safety margin in the object following program?</strong></p><p><strong>Answer</strong>: The primary purpose is to prevent the Mecanum-wheel car from frequently starting and stopping due to minor distance fluctuations, thereby protecting the motors and improving overall stability.</p><p><strong>Q2: What is the key motor control method for making the Mecanum-wheel car turn left when encountering an obstacle ahead?</strong></p><p><strong>Answer</strong>: The ultrasonic sensor detects whether an obstacle is ahead, and if an obstacle is present, the controller commands the motors to turn left. Left steering relies on a speed differential between the left and right wheels, where setting the right wheel rotational speed higher than the left wheel rotational speed turns the car to the left.</p><h2 id="_3-10-7-technical-support-and-discussion" tabindex="-1">3.10.7 Technical Support and Discussion <a class="header-anchor" href="#_3-10-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.10.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',52)])])}const S=r(f,[["render",b]]);export{j as __pageData,S as default};
